// DeleteUniqueIndexCache 删除索引存在的缓存
func (u *UserWxRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.UserWx) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, u.cache.Key(CacheUserWxByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[u.cache.Key(CacheUserWxByIDPrefix, item.ID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserWxByUnionidPrefix, item.Unionid)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserWxByOffiaccountOpenIDPrefix, item.OffiaccountOpenID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := u.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
